/// Whether `name` is one of the special names above.
pub fn is_special_name(name: &str) -> bool {
    SPECIAL_NAMES.binary_search(&name).is_ok()
}

/// Whether `module` (dotted) belongs to the standard library.
pub fn is_stdlib(module: &str) -> bool {
    let top = module.split('.').next().unwrap_or(module);
    STDLIB_MODULES.binary_search(&top).is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sorted_and_known_members() {
        assert!(
            STDLIB_MODULES.windows(2).all(|w| w[0] < w[1]),
            "list must be sorted and unique"
        );
        for m in [
            "os",
            "uuid",
            "_aix_support",
            "lib2to3.pgen2.grammar",
            "test.support",
            "__builtin__",
            "logging.handlers",
        ] {
            assert!(is_stdlib(m), "{m}");
        }
        for m in ["torch", "numpy.core", "aiohttp.client", "__main__", ""] {
            assert!(!is_stdlib(m), "{m}");
        }
        assert!(
            SPECIAL_NAMES.windows(2).all(|w| w[0] < w[1]),
            "special names must be sorted"
        );
        for n in [
            "__setstate__",
            "__reduce__",
            "__class__",
            "__dict__",
            "__globals__",
            "__call__",
        ] {
            assert!(is_special_name(n), "{n}");
        }
        for n in [
            "__FILE_RESOURCE_DATA__",
            "__networkx_cache__",
            "__my_cache__",
            "weights",
        ] {
            assert!(!is_special_name(n), "{n}");
        }
    }
}
